insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000490011', '40000000-0000-4000-8000-000000049001', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000490012', '40000000-0000-4000-8000-000000049001', 'O vetor de A até B é obtido fazendo ponto final menos ponto inicial.', 2), ('60000000-0000-4000-8000-000000490013', '40000000-0000-4000-8000-000000049001', 'Subtraia separadamente as coordenadas x, y e z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049001', '$AB=(2,1,1)$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000490011', '40000000-0000-4000-8000-000000049001', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000490012', '40000000-0000-4000-8000-000000049001', 'Organize a subtração', '$AB=B-A.$', 2), ('70000000-0000-4000-8000-000000490013', '40000000-0000-4000-8000-000000049001', 'Calcule as componentes', '$AB=(3,2,3)-(1,1,2).$', 3), ('70000000-0000-4000-8000-000000490014', '40000000-0000-4000-8000-000000049001', 'Confira o sentido', '$A+AB=(3,2,3)=B$, portanto o sentido está correto.', 4), ('70000000-0000-4000-8000-000000490015', '40000000-0000-4000-8000-000000049001', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
